const query = await import(new URL('variants/query/lib/util.js', root));
const oldUtil = await import(new URL('variants/current/lib/util.js', root));
const wire = await import(new URL('variants/wire/lib/resource.js', root));
const status = await import(new URL('variants/status/lib/index.js', root));
const capture = fn => {try {return {value: fn()};} catch (e) {return {error: e.name, message: e.message};}};
const seeds = [1, 19, 42, 123456789, 0x12345678, 0x9e3779b9, 0xdeadbeef, 0x7fffffff];
let state, queries = 0, queryErrors = 0, hashes = 0, messages = 0, notifications = 0;
const random = () => {state ^= state << 13; state ^= state >>> 17; state ^= state << 5; return (state >>> 0) / 4294967296;};
const pick = a => a[Math.floor(random() * a.length)];
const checksum = createHash('sha256');
for (const seed of seeds) {
  state = seed;
  for (let i = 0; i < 10000; i++) {
    const parts = Array.from({length: Math.floor(random() * 12)}, () => pick(['', 'a', 'z', 'a=b=c', '=v', '=',
      'a=1', 'a=2', '0=z', '09=x', '?a=b', '%3D=%26', 'x=日本語', 'x=😀', 'x=\uD800', 'x=\0', '__proto__=x', 'toString=1', 'constructor=2']));
    const input = pick(['', '?']) + parts.join('&');
    const before = capture(() => oldUtil.orderUrlSearch(input)), after = capture(() => query.orderUrlSearch(input));
    assert.deepEqual(after, before, JSON.stringify({seed, i, input}));
    queries++; if (before.error) queryErrors++;
    assert.equal(query.simpleHashString(input), oldUtil.simpleHashString(input)); hashes++;
    checksum.update(JSON.stringify(before));
  }
}
for (let i = 0; i < 300; i++) {
  const res = current.resource.createResource({type: 1, depth: 1, url: 'https://example.test/a', refUrl: 'https://example.test/', localRoot: '/out'});
  const symbol = Symbol('metadata');
  const cases = [{}, {doc: {fake: true}}, {[symbol]: () => {}}, {headers: {a: 'b'}, values: [1, 2]},
    {date: new Date(0), map: new Map([['a', 1]]), set: new Set([1])}, {buf: Buffer.from('abc')},
    {value: undefined}, {value: Symbol('uncloneable')}, {value: () => {}}, {value: 1n}];
  for (const meta of cases) {
    const input = {...res, meta};
    const before = capture(() => current.resource.prepareResourceForClone(input));
    const after = capture(() => wire.prepareResourceForClone(input));
    assert.deepEqual(after, before);
    if (after.value) {
      assert.notEqual(after.value.meta, meta);
      if (after.value.meta.headers) {after.value.meta.headers.a = 'changed'; assert.equal(meta.headers.a, 'b');}
    }
    messages++;
  }
}
async function notify(api, sequence, rejectIndex) {
  const events = [];
  const options = api.options.defaultDownloadOptions(api.lifeCycle.defaultLifeCycle());
  const res = api.resource.createResource({type: 1, depth: 1, url: 'https://example.test/a', refUrl: 'https://example.test/', localRoot: '/out'});
  options.statusChange = sequence.map((kind, index) => {
    const run = () => {events.push(index); if (index === rejectIndex) throw new Error('listener failure');};
    if (kind === 0) return run;
    if (kind === 1) return async () => {await Promise.resolve(); run();};
    if (kind === 2) return () => ({then(resolve, reject) {queueMicrotask(() => {try {run(); resolve();} catch (e) {reject(e);}});}});
    return () => {events.push(index); return Object.defineProperty({}, 'then', {get() {throw new Error('then getter');}});};
  });
  const pipeline = new api.downloader.PipelineExecutorImpl(options, options.req, options);
  const pending = pipeline.notifyStatusChange(res, 'dispose');
  assert.ok(pending instanceof Promise, 'Promise-returning API must remain available');
  await pending;
  return events;
}
for (const seed of seeds) {
  state = seed;
  for (let i = 0; i < 100; i++) {
    const sequence = Array.from({length: Math.floor(random() * 16)}, () => Math.floor(random() * 4));
    const rejectIndex = Math.floor(random() * (sequence.length + 1)) - 1;
    assert.deepEqual(await notify(status, sequence, rejectIndex), await notify(current, sequence, rejectIndex));
    notifications++; checksum.update(JSON.stringify({sequence, rejectIndex}));
  }
}
const report = {passed: true, seeds, queries, queryErrors, hashes, wireMessages: messages,
  listenerSequences: notifications, checksum: checksum.digest('hex')};
await writeFile(new URL('logs/candidate-equivalence.json', root), JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify(report));

