const candidate = await import(new URL(`variants/${name}/lib/resource.js`, root));
const capture = fn => {try {return {value: fn()};} catch (e) {return {error: e.name, message: e.message};}};
let checks = 0;
for (let round = 0; round < 300; round++) {
  const symbol = Symbol('metadata');
  const cycle = {}; cycle.self = cycle;
  const metas = [{}, {doc: {fake: true}}, {[symbol]: () => {}}, {'': 1},
    {headers: {a: 'b'}, nested: [{x: 1}]}, {date: new Date(0), map: new Map([['a', 1]]), set: new Set([1])},
    {buf: Buffer.from('abc')}, {value: undefined}, {value: Symbol('uncloneable')}, {value: () => {}},
    {value: 1n}, {cycle}, Object.create({inherited: () => {}}),
    Object.defineProperty({}, 'hidden', {value: () => {}}),
    Object.defineProperty({}, 'visible', {enumerable: true, get() {return {x: 1};}})];
  for (const meta of metas) {
    const res = baseline.createResource({type: 1, depth: 1, url: 'https://example.test/a', refUrl: 'https://example.test/', localRoot: '/out'});
