import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {performance} from 'node:perf_hooks';
import {Session} from 'node:inspector/promises';

const root = new URL('../', import.meta.url).pathname;
const descriptions = {
  'status-sync': {items: 2048, description: 'Depth-rejected resources with two synchronous status listeners; initialization and disposal included.'},
  'status-async': {items: 256, description: 'Depth-rejected resources with two asynchronous status listeners; initialization and disposal included.'},
  'query-short': {items: 512, description: 'Full pipeline resource creation retaining short, unsorted repeated query parameters.'},
  'query-long': {items: 512, description: 'Full pipeline resource creation retaining long query parameters, including ordering and save-name hashing.'},
  'wire-empty': {items: 512, description: 'Prepare, structured-clone and decode worker resource messages with empty metadata.'},
  'wire-headers': {items: 512, description: 'Prepare, structured-clone and decode worker resource messages with response headers and custom metadata.'}
};
export const fixtureInfo = Object.fromEntries(
  (process.env.WSE_ENGINE_CASES?.split(',') ?? Object.keys(descriptions))
    .map(key => [key, {...descriptions[key], timingBatches: 2, profileBatches: 4}]));

export async function makeRunner(variant, pressure) {
  const name = variant === 0 ? 'current' : process.env.WSE_CANDIDATE;
  const entry = pathToFileURL(root + 'variants/' + name + '/lib/index.js');
  const api = await import(entry);
  const {withCrawlContext} = await import(new URL('./crawl-context.js', entry));
  const logger = {trace(){}, debug(){}, info(){}, warn(){}, error(){}, isTraceEnabled(){return false;}};
  const directory = await fs.mkdtemp(root + 'tmp/engine-' + variant + '-');
  const config = path.join(directory, 'options.mjs');
  await fs.writeFile(config, `import {lifeCycle, options} from ${JSON.stringify(entry.href)};
export default options.defaultDownloadOptions({...lifeCycle.defaultLifeCycle(), initialUrl: [], maxDepth: 0});`);
  const options = api.options.defaultDownloadOptions({...api.lifeCycle.defaultLifeCycle(),
    initialUrl: [], localRoot: directory, deduplicateStripSearch: false, createLogger: () => logger});
  const controller = new AbortController();
  const context = {logger, signal: controller.signal};
  const pipeline = new api.downloader.PipelineExecutorImpl(options, options.req, options, controller.signal);
  const parent = api.resource.createResource({type: api.resource.ResourceType.Css, depth: 0,
    url: 'https://example.test/docs/page.css', refUrl: 'https://example.test/docs/page.css', localRoot: directory});
  const resources = Array.from({length: 2048}, (_, i) => api.resource.createResource({
    type: api.resource.ResourceType.Binary, depth: 1, url: `https://example.test/img/${i}.png`,
    refUrl: parent.url, localRoot: directory}));
  const indices = new Map(resources.map((res, index) => [res, index]));
  const headers = {'content-type': 'application/octet-stream', 'cache-control': 'max-age=300',
    etag: 'fixture', 'last-modified': 'Sun, 04 Oct 2026 00:00:00 GMT'};
  const wireResources = resources.slice(0, 512).map(res => ({...res, meta: {headers, values: [1, 2, 3], cssProcessed: 1}}));
  const queries = Object.fromEntries(['query-short', 'query-long'].map(key => [key,
    Array.from({length: 512}, (_, i) => `../img/${i}.png?z=${i}&a=one&a=two&b=x=y` +
      (key === 'query-long' ? '&long=' + 'a+b%20c='.repeat(24) + '&c=last' : ''))]));
  let peak = 0;

  async function work(key, batches) {
    const checksum = createHash('sha256');
    let count = 0, live = [];
    const churn = i => {
      if (i % 64) return;
      if (pressure) {
        live.push(new Array(32768).fill(123));
        if (live.length > 8) live.shift();
      }
      peak = Math.max(peak, process.memoryUsage().heapUsed);
    };
    for (let batch = 0; batch < batches; batch++) {
      const items = descriptions[key].items;
      if (key.startsWith('status-')) {
        const events = [];
        const seen = new Uint8Array(items);
        const first = (res, status) => {
          const index = indices.get(res);
          assert.equal(status, 'dispose'); assert.equal(seen[index], 0);
          seen[index] = 1; events.push(index * 2);
        };
        const second = res => {
          const index = indices.get(res);
          assert.equal(seen[index], 1); seen[index] = 2; events.push(index * 2 + 1);
        };
        const statusChange = key === 'status-async' ? [async (...args) => {await Promise.resolve(); first(...args);},
          async (...args) => {await Promise.resolve(); second(...args);}] : [first, second];
        const crawler = new api.downloader.SingleThreadDownloader(pathToFileURL(config).href,
          {localRoot: directory, initialUrl: [], maxDepth: 0, statusChange, createLogger: () => logger});
        try {
          await crawler.init;
          for (let i = 0; i < items; i++) {assert.equal(crawler.addProcessedResource(resources[i]), false); churn(i);}
        } finally {await crawler.dispose();}
        assert.equal(events.length, items * 2);
        events.sort((a, b) => a - b); checksum.update(events.join('\n')); count += items;
      } else if (key.startsWith('query-')) {
        for (let i = 0; i < items; i++) {
          const res = await pipeline.createAndProcessResource(queries[key][i], api.resource.ResourceType.Binary, 1, null, parent);
          assert.ok(res); checksum.update(res.url + '\0' + res.savePath + '\0' + res.replacePath + '\n');
          count++; churn(i);
        }
      } else {
        for (let i = 0; i < items; i++) {
          const res = key === 'wire-empty' ? resources[i] : wireResources[i];
          const wire = api.resource.prepareResourceForClone(res);
          const decoded = api.resource.decodeResourceFromClone(structuredClone(wire));
          assert.equal(decoded.url, res.url);
          checksum.update(decoded.url + '\0' + JSON.stringify(decoded.meta) + '\n');
          count++; churn(i);
        }
      }
    }
    peak = Math.max(peak, process.memoryUsage().heapUsed);
    live = [];
    return {count, sha256: checksum.digest('hex')};
  }

  return {
    async warm(key) {await withCrawlContext(context, () => work(key, 2));},
    async sample(key) {
      global.gc(); const before = process.memoryUsage(); peak = before.heapUsed;
      const start = performance.now(); const result = await withCrawlContext(context, () => work(key, 2));
      const totalMs = performance.now() - start; const after = process.memoryUsage();
      global.gc(); const retained = process.memoryUsage().heapUsed;
      return {case: key, ...result, totalMs, heapBefore: before.heapUsed, heapAfter: after.heapUsed,
        heapPeakObserved: peak, retainedHeapDelta: retained - before.heapUsed, rss: after.rss};
    },
    async profile(key, prefix) {
      global.gc(); const session = new Session(); session.connect();
      await session.post('Profiler.enable'); await session.post('Profiler.start');
      await session.post('HeapProfiler.startSampling', {samplingInterval: 4096,
        includeObjectsCollectedByMajorGC: true, includeObjectsCollectedByMinorGC: true});
      const result = await withCrawlContext(context, () => work(key, 4));
      const {profile} = await session.post('HeapProfiler.stopSampling');
      const {profile: cpu} = await session.post('Profiler.stop'); session.disconnect();
      await fs.writeFile(prefix + '.heapprofile', JSON.stringify(profile));
      await fs.writeFile(prefix + '.cpuprofile', JSON.stringify(cpu));
      const stack = [profile.head]; let sampledBytes = 0;
      while (stack.length) {const node = stack.pop(); sampledBytes += node.selfSize; stack.push(...node.children);}
      return {case: key, ...result, sampledBytes};
    },
    async close() {await fs.rm(directory, {recursive: true, force: true});}
  };
}

