import {performance} from 'node:perf_hooks';
import {promises as fs} from 'node:fs';

let sink = 1;
export function cpuProbe() {
  const started = performance.now();
  for (let i = 0; i < 4000000; i++) sink = Math.imul(sink ^ i, 1664525) + 1013904223 | 0;
  return performance.now() - started;
}
export async function ioProbe(file) {
  const started = performance.now();
  for (let i = 0; i < 8; i++) {
    await fs.stat(file);
    await fs.readFile(file);
  }
  return performance.now() - started;
}
export async function probes(file) {
  return {cpuMs: cpuProbe(), ioMs: await ioProbe(file)};
}

