from pathlib import Path
import collections,hashlib,json,math,statistics
root=Path(__file__).resolve().parent
median=statistics.median
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def interval(values):
 state=123456789;draws=[]
 for _ in range(10000):
  sample=[]
  for _ in values:
   state^=(state<<13)&0xffffffff;state^=state>>17;state^=(state<<5)&0xffffffff;state&=0xffffffff
   sample.append(values[int(state/4294967296*len(values))])
  draws.append(median(sample))
 draws.sort()
 def q(p):
  at=p*(len(draws)-1);lo=math.floor(at);hi=math.ceil(at)
  return draws[lo]+(draws[hi]-draws[lo])*(at-lo)
 return {'median':median(values),'interval95':[q(.025),q(.975)]}
def equal(a,b):
 if isinstance(a,dict):
  assert a.keys()==b.keys()
  for k in a:equal(a[k],b[k])
 elif isinstance(a,list):
  assert len(a)==len(b)
  for x,y in zip(a,b):equal(x,y)
 else:assert math.isclose(a,b,rel_tol=1e-9,abs_tol=1e-9),(a,b)
def maxima(rows):
 assert len(rows)==6
 assert collections.Counter((x['variant'],x['sample']) for x in rows)==collections.Counter((v,s) for v in range(3) for s in range(2))
 return {m:max(x[w][m] for x in rows for w in ['noiseBefore','noiseAfter']) for m in ['cpuMs','ioMs']}
for name,fingerprint in read(root/'frozen.json')['files'].items():assert sha(root/name)==fingerprint,name
verified=[]
for path in sorted(root.glob('runs/combined-*-timing.json')):
 d=read(path)
 assert d['protocol']['rounds']==12 and d['protocol']['minimumQualifyingRounds']==8
 for c in d['comparisons']:
  key=c['case'];rows=[x for x in d['samples'] if x['case']==key];cal=[x for x in d['calibration'] if x['case']==key]
  assert len({(x['sha256'],x['count']) for x in rows+cal})==1
  mx=[maxima([x for x in cal if x['round']==i]) for i in range(3)]
  t={m:1.5*median(x[m] for x in mx) for m in ['cpuMs','ioMs']};equal(t,d['thresholds'][key])
  excluded=[];med=[];positions=collections.Counter()
  for i in range(12):
   group=[x for x in rows if x['round']==i];mx=maxima(group)
   order=[0,1,2];offset=(i+3)%3;order=order[offset:]+order[:offset]
   if (i+3)%2:order.reverse()
   assert [x['variant'] for x in group]==[v for v in order for _ in range(2)]
   positions.update((v,p) for p,v in enumerate(order))
   bad=[m for m in t if mx[m]>t[m]]
   if bad:excluded.append({'round':i,'metrics':bad})
   else:med.append([median(x['totalMs'] for x in group if x['variant']==v) for v in range(3)])
  assert set(positions.values())=={4}
  assert excluded==c['excluded'];assert len(med)==c['acceptedRounds']
  if len(med)<8:assert c['status']=='insufficient-rounds';continue
  equal([median(x[v] for x in med) for v in range(3)],c['medianMs'])
  for name,values in [('control',[100*(x[2]/x[1]-1) for x in med]),('effect',[100*(x[1]/x[0]-1) for x in med]),('effectControl',[100*(x[2]/x[0]-1) for x in med])]:equal(interval(values),c[name])
  lo,hi=c['control']['interval95'];stable=-5<=lo<=0<=hi<=5
  status='unresolved-control' if not stable else 'faster' if max(c['effect']['interval95'][1],c['effectControl']['interval95'][1])<0 else 'slower' if min(c['effect']['interval95'][0],c['effectControl']['interval95'][0])>0 else 'unresolved-difference'
  assert c['status']==status
 verified.append(path.name)
profiles=[]
for path in sorted(root.glob('runs/*-profile.json')):
 d=read(path);prefix=path.name.removesuffix('-profile.json');keys=list(d['protocol']['fixtureInfo'])
 assert len(d['samples'])==9*len(keys)
 assert len({(x['round'],x['variant'],x['case']) for x in d['samples']})==len(d['samples'])
 for key in keys:assert len({(x['sha256'],x['count']) for x in d['samples'] if x['case']==key})==1
 for x in d['samples']:
  p=root/f'profiles/{prefix}-r{x["round"]}-v{x["variant"]}-{x["case"]}.heapprofile'
  stack=[read(p)['head']];total=0
  while stack:
   node=stack.pop();total+=node['selfSize'];stack.extend(node['children'])
  assert total==x['sampledBytes'],p
 profiles.append(path.name)
print(json.dumps({'verifiedTimingCampaigns':verified,'verifiedAllocationCampaigns':profiles,
                  'frozenFilesUnchanged':True,'calibrationExclusionsBalancedOrderOutputHashesAndBootstrapIntervals':True}))
